-- Restore compatible LeadPilot agent tables under the company schema.
alter table public.businesses add column if not exists account_id uuid;
alter table public.leads add column if not exists account_id uuid;
update public.businesses set account_id=company_id where account_id is null;
update public.leads set account_id=company_id where account_id is null;
alter table public.businesses alter column account_id set not null;
alter table public.leads alter column account_id set not null;
create index if not exists businesses_account_idx on public.businesses(account_id);
create index if not exists leads_account_idx on public.leads(account_id);

create table if not exists public.lead_imports(id uuid primary key default gen_random_uuid(),account_id uuid not null,company_id uuid not null references public.companies(id) on delete cascade,source text not null,imported integer not null default 0,valid integer not null default 0,duplicates integer not null default 0,rejected integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.verification_checks(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads(id) on delete cascade,check_type text not null,status text not null,evidence text not null,checked_at timestamptz not null default now());
create index if not exists verification_checks_lead_idx on public.verification_checks(lead_id,checked_at desc);
create table if not exists public.score_factors(id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads(id) on delete cascade,factor text not null,points integer not null,explanation text not null,created_at timestamptz not null default now());
create index if not exists score_factors_lead_idx on public.score_factors(lead_id);
create table if not exists public.activities(id uuid primary key default gen_random_uuid(),account_id uuid not null,company_id uuid not null references public.companies(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,type text not null,description text not null,created_at timestamptz not null default now());
create table if not exists public.status_history(id uuid primary key default gen_random_uuid(),account_id uuid not null,company_id uuid not null references public.companies(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,old_status text,new_status text not null,created_at timestamptz not null default now());
create table if not exists public.agent_memory(id uuid primary key default gen_random_uuid(),account_id uuid not null,lead_id uuid,business_id uuid,conversation_id uuid,scope text not null check(scope in ('account','lead','conversation','system')),memory_type text not null,content jsonb not null,source text,confidence numeric(5,4),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_agent_memory_account on public.agent_memory(account_id);
create table if not exists public.agent_events(event_id uuid primary key default gen_random_uuid(),account_id uuid not null,lead_id uuid,agent text not null,event_type text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists idx_agent_events_lead_created on public.agent_events(lead_id,created_at desc);
create table if not exists public.agent_schedules(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,agent_id text not null,query text not null,location text,industry text,limit_count integer not null default 10 check(limit_count between 1 and 100),frequency text not null check(frequency in ('hourly','daily','weekly')),active boolean not null default true,next_run_at timestamptz not null default now(),last_run_at timestamptz,last_status text,last_result_count integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists agent_schedules_due_idx on public.agent_schedules(active,next_run_at);
create index if not exists agent_schedules_user_idx on public.agent_schedules(user_id);
create table if not exists public.revenue_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,lead_id text,agent_id text,event text not null check(event in ('qualified','draft_created','contacted','replied','meeting_booked','won','lost')),value numeric not null default 0,currency text not null default 'USD',occurred_at timestamptz not null default now(),created_at timestamptz not null default now());
create index if not exists revenue_events_user_agent_idx on public.revenue_events(user_id,agent_id,occurred_at desc);
create table if not exists public.payment_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,reference text not null unique,provider text not null default 'paystack',status text not null default 'initialized' check(status in ('initialized','success','failed','reversed')),amount bigint not null default 0,currency text not null default 'NGN',lead_id text,agent_id text,offer_name text,provider_transaction_id text,paid_at timestamptz,raw_event jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists payment_transactions_user_idx on public.payment_transactions(user_id);
create index if not exists payment_transactions_provider_id_idx on public.payment_transactions(provider_transaction_id);
create table if not exists public.processed_payment_events(id uuid primary key default gen_random_uuid(),provider text not null default 'paystack',event_id text not null unique,reference text,received_at timestamptz not null default now());

alter table public.lead_imports enable row level security;
alter table public.verification_checks enable row level security;
alter table public.score_factors enable row level security;
alter table public.activities enable row level security;
alter table public.status_history enable row level security;
alter table public.agent_memory enable row level security;
alter table public.agent_events enable row level security;
alter table public.agent_schedules enable row level security;
alter table public.revenue_events enable row level security;
alter table public.payment_transactions enable row level security;
alter table public.processed_payment_events enable row level security;
create policy "lead imports company read" on public.lead_imports for select to authenticated using(private.is_company_member(company_id));
create policy "lead imports company insert" on public.lead_imports for insert to authenticated with check(private.has_company_role(company_id,array['owner','admin','member']));
create policy "verification company read" on public.verification_checks for select to authenticated using(exists(select 1 from public.leads l where l.id=lead_id and private.is_company_member(l.company_id)));
create policy "verification company insert" on public.verification_checks for insert to authenticated with check(exists(select 1 from public.leads l where l.id=lead_id and private.has_company_role(l.company_id,array['owner','admin','member'])));
create policy "score factors company read" on public.score_factors for select to authenticated using(exists(select 1 from public.leads l where l.id=lead_id and private.is_company_member(l.company_id)));
create policy "score factors company insert" on public.score_factors for insert to authenticated with check(exists(select 1 from public.leads l where l.id=lead_id and private.has_company_role(l.company_id,array['owner','admin','member'])));
create policy "activities company read" on public.activities for select to authenticated using(private.is_company_member(company_id));
create policy "activities company insert" on public.activities for insert to authenticated with check(private.has_company_role(company_id,array['owner','admin','member']));
create policy "activities company update" on public.activities for update to authenticated using(private.has_company_role(company_id,array['owner','admin','member'])) with check(private.has_company_role(company_id,array['owner','admin','member']));
create policy "activities company delete" on public.activities for delete to authenticated using(private.has_company_role(company_id,array['owner','admin','member']));
create policy "status history company read" on public.status_history for select to authenticated using(private.is_company_member(company_id));
create policy "status history company insert" on public.status_history for insert to authenticated with check(private.has_company_role(company_id,array['owner','admin','member']));
create policy "status history company update" on public.status_history for update to authenticated using(private.has_company_role(company_id,array['owner','admin','member'])) with check(private.has_company_role(company_id,array['owner','admin','member']));
create policy "status history company delete" on public.status_history for delete to authenticated using(private.has_company_role(company_id,array['owner','admin','member']));
revoke all on public.agent_memory,public.agent_events from anon,authenticated;
create policy "user schedules own" on public.agent_schedules for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "user revenue read own" on public.revenue_events for select to authenticated using(user_id=(select auth.uid()));
revoke insert,update,delete on public.revenue_events from anon,authenticated;
create policy "user payments read own" on public.payment_transactions for select to authenticated using(user_id=(select auth.uid()));
revoke insert,update,delete on public.payment_transactions from anon,authenticated;
alter table public.processed_payment_events set schema private;
revoke all on private.processed_payment_events from public,anon,authenticated;
